#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

char *join_new(const char *sep, ...)
{
    va_list args, again;
    va_start(args, sep);
    va_copy(again, args);

    size_t length = 0;
    size_t count = 0;
    for (const char *s = va_arg(args, const char *); s != NULL; s = va_arg(args, const char *))
    {
        length += strlen(s);
        count++;
    }
    va_end(args);
    if (count > 1)
        length += strlen(sep) * (count - 1);

    char *out = malloc(length + 1);
    if (out != NULL)
    {
        char *end = out;
        size_t i = 0;
        for (const char *s = va_arg(again, const char *); s != NULL; s = va_arg(again, const char *), i++)
        {
            if (i > 0)
            {
                size_t n = strlen(sep);
                memcpy(end, sep, n);
                end += n;
            }
            size_t n = strlen(s);
            memcpy(end, s, n);
            end += n;
        }
        *end = '\0';
    }
    va_end(again);
    return out;
}

char *format_new(const char *format, ...)
{
    va_list args, again;
    va_start(args, format);
    va_copy(again, args);
    int needed = vsnprintf(NULL, 0, format, args);
    va_end(args);
    char *text = needed >= 0 ? malloc((size_t)needed + 1) : NULL;
    if (text != NULL)
        vsnprintf(text, (size_t)needed + 1, format, again);
    va_end(again);
    return text;
}

unitTests:
TEST("joining") { char *s = join_new(", ", "red", "green", "blue", (const char *)NULL); CHECK_STR(s, "red, green, blue"); CHECK_EQ((int)strlen(s), 16); free(s); }
TEST("one and none") { char *one = join_new("-", "solo", (const char *)NULL); CHECK_STR(one, "solo"); free(one); char *none = join_new("-", (const char *)NULL); CHECK(none != NULL); CHECK_STR(none, ""); free(none); }
TEST("empty pieces and long separators") { char *s = join_new(" <> ", "", "x", "", (const char *)NULL); CHECK_STR(s, " <> x <> "); free(s); }
TEST("formatting") { char *s = format_new("%s scored %d (%.1f%%)", "Ada", 42, 87.5); CHECK_STR(s, "Ada scored 42 (87.5%)"); free(s); char *e = format_new("%s", ""); CHECK_STR(e, ""); free(e); }

